package com.example.motionspeak

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.abs

/**
 * Real JVM/Kotlin execution test harness verifying byte-for-byte numerical parity
 * against Python motionspeak-ml preprocessor.normalize_frame across all 147 features.
 */
class FeatureParityTest {

    data class DriftStats(val maxError: Float, val meanError: Float, val maxIdx: Int, val maxExpected: Float, val maxActual: Float)

    private fun compareVectors(name: String, input: FloatArray, expected: FloatArray): DriftStats {
        val actual = input.copyOf()
        normalizeFrame(actual)
        var maxDiff = 0f
        var totalDiff = 0.0
        var maxIdx = 0
        for (i in 0 until 147) {
            val diff = abs(actual[i] - expected[i])
            totalDiff += diff
            if (diff > maxDiff) {
                maxDiff = diff
                maxIdx = i
            }
            val tol = maxOf(2e-5f, abs(expected[i]) * 1e-4f)
            if (diff > tol) {
                throw AssertionError("Case " + name + " at index " + i + ": expected " + expected[i] + " got " + actual[i] + " diff=" + diff)
            }
        }
        val meanDiff = (totalDiff / 147.0).toFloat()
        println("Parity verified for [" + name + "]: maxError=" + maxDiff + " at index " + maxIdx + " (exp=" + expected[maxIdx] + ", act=" + actual[maxIdx] + "), meanError=" + meanDiff)
        return DriftStats(maxDiff, meanDiff, maxIdx, expected[maxIdx], actual[maxIdx])
    }

