    @Test
    fun testMissingHandPreservesZeroSentinel() {
        val frame = FloatArray(147)
        frame[0] = 0.5f; frame[1] = 0.5f; frame[2] = 0.0f
        frame[27] = 0.55f; frame[28] = 0.45f; frame[29] = 0.0f
        frame[129] = 0.4f; frame[130] = 0.4f; frame[132] = 0.6f; frame[133] = 0.4f
        normalizeFrame(frame)
        for (i in 63 until 126) {
            assertEquals("Slot 1 absent hand must remain exactly 0.0f at index " + i, 0.0f, frame[i], 0.0f)
        }
    }

    @Test
    fun testMissingPosePreservesZeroSentinel() {
        val frame = FloatArray(147)
        frame[0] = 0.5f; frame[1] = 0.5f; frame[2] = 0.0f
        frame[27] = 0.55f; frame[28] = 0.45f; frame[29] = 0.0f
        normalizeFrame(frame)
        for (i in 126 until 147) {
            assertEquals("Absent pose must remain exactly 0.0f at index " + i, 0.0f, frame[i], 0.0f)
        }
    }

    @Test
    fun testHandExtentGate() {
        // A realistic hand where all 21 points are within 0.1 of wrist (0.5, 0.5)
        val normal = FloatArray(147)
        for (j in 0 until 21) {
            normal[j * 3]     = 0.50f + (j % 5) * 0.015f
            normal[j * 3 + 1] = 0.50f + (j / 5) * 0.020f
        }
        normalizeFrame(normal)
        assertTrue("Normal hand should be accepted", handExtentOk(normal))

        val absent = FloatArray(147)
        assertTrue("Absent hands should be accepted", handExtentOk(absent))

        // Collapsed hand: wrist and MCP9 are 0.00001 apart, scaling distant fingertip 30000x
        val collapsed = FloatArray(147)
        collapsed[0] = 0.5f; collapsed[1] = 0.5f
        collapsed[27] = 0.50001f; collapsed[28] = 0.50001f
        collapsed[12] = 0.8f; collapsed[13] = 0.9f
        normalizeFrame(collapsed)
        assertFalse("Collapsed hand must be rejected", handExtentOk(collapsed))
    }

    @Test
    fun testLayoutConstants() {
        assertEquals(147, FEATURE_SIZE_147)
        assertEquals(126, POSE_BASE_147)
        assertEquals(1, POSE_LSHOULDER_147)
        assertEquals(2, POSE_RSHOULDER_147)
        assertEquals(listOf(0, 11, 12, 13, 14, 15, 16), POSE_KEYPOINTS.toList())
    }
}